#include <linux/personality.h>
#include <linux/utsname.h>
#include <linux/uaccess.h>
#include <linux/version.h>

int compat_get_uname_26(char __user *release, size_t len)
{
    static char compat_release[26];
    int ret = 0;

    if (current->personality & UNAME26) {
        snprintf(compat_release, sizeof(compat_release),
                 "Linux 2.6.%d", LINUX_VERSION_CODE & 0xFF);
        ret = strnlen(compat_release, sizeof(compat_release));
        if (ret > 0 && len > 0) {
            if (ret > len)
                ret = len;
            if (copy_to_user(release, compat_release, ret))
                ret = -EFAULT;
        }
    }

    return ret;
}

int compat_get_old_linux_version(char __user *release, size_t len) {
    int res = 0;
    char compat_version[27];
    const char *orig_version = "Linux 2.6.0";

    if (personality(current->personality) & UNAME26) {
        /* Use the provided version string for compatibility. */
        res = snprintf(compat_version, sizeof(compat_version), "%s", orig_version);

        if (res >= 0 && res < len) {
            if (copy_to_user(release, compat_version, res))
                return -EFAULT;
            return res;
        } else {
            return -EINVAL;
        }
    }
    return 0;
}

#include <linux/personality.h>
#include <linux/version.h>
#include <asm/uaccess.h>

int compat_get_uname_26(char __user *release, size_t len) {
    int err;
    char compat_release[27];

    if (current->personality & UNAME26) {
        /* Format the version string in the 2.6.x style */
        int version = LINUX_VERSION_CODE;
        int major = (version >> 16) & 0xFF;
        int minor = (version >> 8) & 0xFF;
        int patch = version & 0xFF;
        int compat_patch = (major * 100) + minor;

        snprintf(compat_release, sizeof(compat_release), "Linux 2.6.%d", compat_patch);
        err = strnlen(compat_release, sizeof(compat_release));
        if (err >= len)
            return -ENAMETOOLONG;
        if (copy_to_user(release, compat_release, err))
            return -EFAULT;
        return err;
    }

    return -EPERM;
}

int compat_set_personality_uname(char __user *release, size_t len) {
    int i;
    char compat_release[27];
    unsigned int version = LINUX_VERSION_CODE;

    if (current_personality() != 0x26) {
        return -EPERM;
    }

    compat_release[0] = 'L';
    compat_release[1] = 'i';
    compat_release[2] = 'n';
    compat_release[3] = 'u';
    compat_release[4] = 'x';
    compat_release[5] = ' ';
    compat_release[6] = '2';
    compat_release[7] = '.';
    compat_release[8] = '6';
    compat_release[9] = '.';
    compat_release[10] = (version / 100) % 10 + '0';
    compat_release[11] = (version / 10) % 10 + '0';
    compat_release[12] = '\0';

    for (i = 13; i < 26; i++) {
        compat_release[i] = ' ';
    }
    compat_release[26] = '\0';

    if (len > 26) {
        len = 26;
    }

    if (copy_to_user(release, compat_release, len)) {
        return -EFAULT;
    }

    return len;
}

#include <linux/personality.h>
#include <linux/version.h>
#include <string.h>
#include <limits.h>

int modify_uname_version(char __user *release, size_t len) {
    char version_string[27];
    unsigned long version_code = LINUX_VERSION_CODE;

    if (current->personality & UNAME26) {
        int major = 2;
        int minor = 6;
        int patch = (version_code >> 16) & 0xFF;

        if (snprintf(version_string, sizeof(version_string), "Linux 2.6.%d", patch) >= sizeof(version_string)) {
            return -EINVAL;
        }

        if (len < strlen(version_string)) {
            return -ENAMETOOLONG;
        }

        if (copy_to_user(release, version_string, strlen(version_string))) {
            return -EFAULT;
        }

        return strlen(version_string);
    }

    return -EPERM;
}
